main{max-width:640px;margin:0 auto;padding:var(--ui-padding);font-family:var(--ui-font);color:var(--ui-text)}
h1{font-size:var(--ui-size-title);margin:0 0 var(--ui-space-2);font-weight:600}
h2{font-size:var(--ui-size-section);font-weight:600;margin:var(--ui-space-5) 0 var(--ui-space-2)}
.sec{color:var(--ui-text-secondary);margin:0 0 var(--ui-space-4)}
.sec strong{color:var(--ui-text);font-weight:600}
ul{list-style:none;margin:0;padding:0}
li{display:flex;align-items:center;gap:var(--ui-space-3);padding:var(--ui-space-2) 0;border-bottom:1px solid var(--ui-divider)}
li .n{flex:1;overflow-wrap:anywhere}
.row{display:flex;flex-wrap:wrap;gap:var(--ui-space-3);align-items:flex-end}
.f{display:flex;flex-direction:column;gap:var(--ui-space-1);flex:1 1 140px}
input{min-height:var(--ui-target);padding:0 var(--ui-space-3);border:1px solid var(--ui-control-border);border-radius:var(--ui-radius-control);background:var(--ui-surface);color:var(--ui-text);font:inherit}
button{min-height:var(--ui-target);padding:0 var(--ui-space-4);border:1px solid var(--ui-control-border);border-radius:var(--ui-radius-control);background:var(--ui-surface);color:var(--ui-text);font:inherit;cursor:pointer}
#add{background:var(--ui-accent);border-color:var(--ui-accent);color:#fff}
:focus-visible{outline:3px solid var(--ui-accent);outline-offset:2px}
#msg{min-height:1.5em;color:var(--ui-text-secondary)}
#msg.err{color:var(--ui-error)}

code.js:
let entries=[],revs={};
const $=id=>document.getElementById(id);
function say(t,err){const m=$('msg');m.textContent=t;m.className=err?'err':'';}
function fmt(n){return String(Math.round(n*100)/100);}
function render(){
 const list=$('list');list.textContent='';
 let sum=0;
 for(const e of entries){
  sum+=e.amount;
  const li=document.createElement('li');
  const n=document.createElement('span');n.className='n';n.textContent=e.name;
  const a=document.createElement('span');a.textContent=fmt(e.amount);
  const b=document.createElement('button');b.type='button';b.textContent='Remove';
  b.setAttribute('aria-label','Remove '+e.name);
  b.addEventListener('click',()=>remove(e.id));
  li.append(n,a,b);list.appendChild(li);
 }
 $('total').textContent=fmt(sum);
 const has=entries.length>0;
 $('empty').hidden=has;$('chartbox').hidden=!has;
 if(has){tessera.chart($('chartbox'),{type:'pie',title:'Spending this month',labels:entries.map(e=>e.name.slice(0,80)),series:[{name:'Spending',values:entries.map(e=>e.amount)}]});}
}
async function load(){
 const r=await tessera.call('data.read',{});
 entries=(r.data.entries||[]);revs=(r.revisions.entries||{});
 render();
}
async function add(){
 const name=$('nm').value.trim();const raw=$('vl').value;const v=Number(raw);
 if(!name){say('Type a name for the entry.',true);$('nm').focus();return;}
 if(raw===''||!isFinite(v)||v<0){say('Type an amount of 0 or more.',true);$('vl').focus();return;}
 try{
  await tessera.call('data.patch',{operations:[{op:'add',collection:'entries',record:{name:name,amount:v}}]});
  $('nm').value='';$('vl').value='';
  await load();say('Added '+name+'.');$('nm').focus();
 }catch(e){say('Could not add the entry. Your text is still here; try again.',true);}
}
async function remove(id){
 const e=entries.find(x=>x.id===id);
 try{
  await tessera.call('data.patch',{operations:[{op:'remove',collection:'entries',id:id,revisionCount:revs[id]}]});
  await load();say('Removed '+(e?e.name:'entry')+'.');$('nm').focus();
 }catch(err){say('Could not remove the entry. Try again.',true);}
}
$('add').addEventListener('click',add);
for(const id of ['nm','vl']){$(id).addEventListener('keydown',ev=>{if(ev.key==='Enter'){ev.preventDefault();add();}});}
load().catch(()=>say('Could not load your entries.',true));

